import sys

def generate_powerful_numbers(limit):
    powers_of_two = [2**i for i in range(40) if 2**i <= limit]
    factorials = [1]
    current_factorial = 1
    for i in range(2, 25):
        current_factorial *= i
        if current_factorial > limit:
            break
        factorials.append(current_factorial)
    return set(powers_of_two + factorials)

def find_min_k(n, powerful_numbers):
    if n in powerful_numbers:
        return 1
    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    for num in powerful_numbers:
        for i in range(n, num - 1, -1):
            dp[i] = min(dp[i], dp[i - num] + 1)
    return dp[n] if dp[n] != float('inf') else -1

powerful_numbers = generate_powerful_numbers(10**12)

t = int(sys.stdin.readline())
results = []
for _ in range(t):
    n = int(sys.stdin.readline())
    results.append(find_min_k(n, powerful_numbers))

print('\n'.join(map(str, results)))
